/// Returns the index of `target` in a sorted slice, or `None` if absent.
pub fn binary_search<T: Ord>(slice: &[T], target: &T) -> Option<usize> {
    let mut lo = 0usize;
    let mut hi = slice.len(); // exclusive upper bound

    while lo < hi {
        // Avoid overflow: (lo + hi) / 2 can overflow for huge slices
        let mid = lo + (hi - lo) / 2;

        match slice[mid].cmp(target) {
            std::cmp::Ordering::Less    => lo = mid + 1,
            std::cmp::Ordering::Greater => hi = mid,
            std::cmp::Ordering::Equal   => return Some(mid),
        }

